INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (21, 0, "", "", "", 16414, 0, 16414067, "", "vo_wac_16414", "vo_wac_16414_000");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (11, 10, 0, 0, 0.5, 16414, 1, 16414068, 1, 105311, "私の誕生日祝い、だと……？\nな、なんと巨大なケーキだ！\nそれにとんでもなく香しい匂いが……！\nこれを私のために……？");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (91, "", "", "", "", 16414, "", 16414069, "", 0, "");
