INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (3, 1, 0.2, "", "", 18814, "", 18814084, "", 100911, "wac_birthday_talk_doya");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (21, 0, "", "", "", 18814, 0, 18814085, "", "vo_wac_18814", "vo_wac_18814_003");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (11, 10, 0, 0, 0.5, 18814, 1, 18814086, 1, 100911, "シグルドからも助言を得ている。\nナナカ生誕を祝すのにふさわしい、\n伝説級の品々を用意してあるぞ？\n限定魔法少女グッズの詰め合わせだ！");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (91, "", "", "", "", 18814, "", 18814087, "", 0, "");
