INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (21, 0, "", "", "", 25214, 0, 25214074, "", "vo_wac_25214", "vo_wac_25214_004");
