INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (3, 1, 0.2, "", "", 30314, "", 30314088, "", 105911, "wac_birthday_talk_smile");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (21, 0, "", "", "", 30314, 0, 30314089, "", "vo_wac_30314", "vo_wac_30314_005");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (11, 10, 0, 0, 0.5, 30314, 1, 30314090, 1, 105911, "わかっております、シェフィさま。\nそれでも……お二人は、あなたを\n大切に想っているのです。\nもちろん、わたくしと主さまも。");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (91, "", "", "", "", 30314, "", 30314091, "", 0, "");
