INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (3, 1, 0.2, "", "", 30314, "", 30314093, "", 106411, "wac_birthday_shefy_talk_wish");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (21, 0, "", "", "", 30314, 0, 30314094, "", "vo_wac_30314", "vo_wac_30314_006");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (11, 10, 0, 0, 0.5, 30314, 1, 30314095, 1, 106411, "……うん。\n改めて、本当にありがとう。\n私、みんなと出会えてよかった。\n今日のこと……絶対、忘れないから♪");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (91, "", "", "", "", 30314, "", 30314096, "", 0, "");
