INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (21, 0, "", "", "", 32314, 0, 32314072, "", "vo_wac_32314", "vo_wac_32314_003");
