INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (21, 0, "", "", "", 37914, 0, 37914071, "", "vo_wac_37914", "vo_wac_37914_003");
