INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (11, 10, 0, 0, 0.5, 39114, 1, 39114078, 1, 103411, "麦しゅわの助けも借りながら、\nみんなで協力して、\n全部乗り越えることができたもの！");
INSERT INTO `v1_6e9e216b8282966ae6e9d0ac246ff45e533aa468fe1abd540d0f1692bf2fafab` VALUES (91, "", "", "", "", 39114, "", 39114079, "", 0, "");
